CREATE OR REPLACE FUNCTION private.base_supported(p text) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT p=ANY(ARRAY['sale_work.access','sale_work.view_own','sale_work.manage_settings','sale_work.manage_credentials','sale_work.view_audit','biz.crm_use','biz.crm_archive','biz.crm_export']) $$;
CREATE OR REPLACE FUNCTION private.base_valid_at(r jsonb) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT coalesce((r->>'active')::boolean,false) AND (nullif(r->>'starts_at','') IS NULL OR (r->>'starts_at')::timestamptz<=now()) AND (nullif(r->>'ends_at','') IS NULL OR (r->>'ends_at')::timestamptz>now()) $$;
CREATE OR REPLACE FUNCTION private.base_config() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT config FROM base_org_state WHERE id=true),'{"units":[],"titles":[],"memberships":[],"defaults":[],"bundles":[],"grants":[],"bindings":[]}'::jsonb) $$;
CREATE OR REPLACE FUNCTION private.base_rules(u uuid,c jsonb) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH RECURSIVE member AS (SELECT m FROM jsonb_array_elements(c->'memberships') m WHERE m->>'user_id'=u::text AND private.base_valid_at(m)),ancestors AS (SELECT x->>'id' id,x->>'parent_id' parent_id FROM jsonb_array_elements(c->'units') x JOIN member ON x->>'id'=member.m->>'unit_id' WHERE coalesce((x->>'active')::boolean,true) UNION SELECT x->>'id',x->>'parent_id' FROM jsonb_array_elements(c->'units') x JOIN ancestors a ON x->>'id'=a.parent_id WHERE coalesce((x->>'active')::boolean,true)),rules AS (SELECT r||jsonb_build_object('source_kind','direct','source_id',r->>'id') r FROM jsonb_array_elements(c->'grants') r WHERE r->>'user_id'=u::text UNION ALL SELECT r||jsonb_build_object('source_kind','default','source_id',d->>'id','source_name',d->>'name') FROM jsonb_array_elements(c->'defaults') d CROSS JOIN LATERAL jsonb_array_elements(d->'rules') r WHERE private.base_valid_at(d) AND ((d->>'unit_id' IS NOT NULL AND EXISTS(SELECT 1 FROM ancestors WHERE id=d->>'unit_id')) OR (d->>'title_id' IS NOT NULL AND EXISTS(SELECT 1 FROM member WHERE m->>'title_id'=d->>'title_id'))) UNION ALL SELECT r||jsonb_build_object('source_kind','bundle','source_id',b->>'id','source_name',b->>'name') FROM jsonb_array_elements(c->'bindings') a JOIN LATERAL jsonb_array_elements(c->'bundles') b ON b->>'id'=a->>'bundle_id' CROSS JOIN LATERAL jsonb_array_elements(b->'rules') r WHERE a->>'user_id'=u::text AND private.base_valid_at(a) AND private.base_valid_at(b)) SELECT coalesce(jsonb_agg(r),'[]'::jsonb) FROM rules WHERE private.base_valid_at(r) $$;
CREATE OR REPLACE FUNCTION private.base_decision(u uuid,p text,c jsonb) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(private.base_rules(u,c)) r WHERE r->>'permission'=p AND r->>'effect'='DENY') THEN 'DENY' WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(private.base_rules(u,c)) r WHERE r->>'permission'=p AND r->>'effect'='ALLOW') THEN 'ALLOW' ELSE 'NOT_CONFIGURED' END $$;
CREATE OR REPLACE FUNCTION private.base_tier1(u uuid,p text) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN private.base_supported(p) THEN private.base_decision(u,p,private.base_config()) ELSE 'NOT_CONFIGURED' END $$;
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.crm_can(uuid,text)'::regprocedure) INTO d;d:=replace(d,'FUNCTION public.crm_can(','FUNCTION private.base_crm_legacy(');EXECUTE d;END $$;
CREATE OR REPLACE FUNCTION public.crm_can(_actor uuid,_permission text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE d text;BEGIN IF NOT private.is_active(_actor) THEN RETURN false;END IF;IF public.biz_admin(_actor) THEN RETURN private.base_crm_legacy(_actor,_permission);END IF;d:=private.base_tier1(_actor,_permission);IF d='DENY' THEN RETURN false;END IF;IF d='ALLOW' THEN RETURN true;END IF;RETURN private.base_crm_legacy(_actor,_permission);END $$;
CREATE OR REPLACE FUNCTION private.has_permission(_user_id uuid,_permission text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT private.is_active(_user_id) AND (private.is_super_admin(_user_id) OR CASE WHEN _permission LIKE 'sale_work.%' AND private.base_tier1(_user_id,_permission)='DENY' THEN false WHEN _permission LIKE 'sale_work.%' AND private.base_tier1(_user_id,_permission)='ALLOW' THEN true WHEN EXISTS(SELECT 1 FROM user_permission_overrides WHERE user_id=_user_id AND use_custom=true) THEN EXISTS(SELECT 1 FROM user_permission_overrides WHERE user_id=_user_id AND _permission=ANY(permissions)) ELSE EXISTS(SELECT 1 FROM user_roles ur JOIN app_roles r ON r.id=ur.role_id WHERE ur.user_id=_user_id AND _permission=ANY(r.permissions)) END) $$;
CREATE OR REPLACE FUNCTION private.base_legacy(u uuid,p text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE allowed boolean:=false;src jsonb;BEGIN IF p LIKE 'biz.crm_%' THEN allowed:=private.base_crm_legacy(u,p);src:='{"kind":"business","tier":2}';ELSIF p LIKE 'biz.%' THEN allowed:=public.biz_can(u,p);src:='{"kind":"business","tier":2}';ELSIF p LIKE 'k3.%' THEN allowed:=public.k3_can(u,p);src:='{"kind":"business","tier":2}';ELSE IF EXISTS(SELECT 1 FROM user_permission_overrides WHERE user_id=u AND use_custom) THEN SELECT p=ANY(permissions) INTO allowed FROM user_permission_overrides WHERE user_id=u;src:='{"kind":"custom","tier":3}';ELSE SELECT coalesce(bool_or(p=ANY(r.permissions)),false) INTO allowed FROM user_roles ur JOIN app_roles r ON r.id=ur.role_id WHERE ur.user_id=u;SELECT jsonb_build_object('kind','role','tier',3,'names',coalesce(jsonb_agg(r.name),'[]')) INTO src FROM user_roles ur JOIN app_roles r ON r.id=ur.role_id WHERE ur.user_id=u;END IF;END IF;RETURN jsonb_build_object('allowed',coalesce(allowed,false),'source',src);END $$;
CREATE OR REPLACE FUNCTION private.base_effective(u uuid,c jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb:='[]';r record;d text;l jsonb;ok boolean;privileged boolean;active boolean;rules jsonb;BEGIN active:=private.is_active(u);privileged:=private.is_super_admin(u);rules:=private.base_rules(u,c);FOR r IN SELECT * FROM base_permission_catalog ORDER BY module,key LOOP d:=CASE WHEN private.base_supported(r.key) THEN private.base_decision(u,r.key,c) ELSE 'NOT_CONFIGURED' END;l:=private.base_legacy(u,r.key);ok:=active AND (privileged OR (r.key LIKE 'biz.crm_%' AND public.biz_admin(u)) OR CASE WHEN d='DENY' THEN false WHEN d='ALLOW' THEN true ELSE (l->>'allowed')::boolean END);result:=result||jsonb_build_array(jsonb_build_object('key',r.key,'label',r.label,'module',r.module,'allowed',ok,'decision',d,'tier',CASE WHEN privileged THEN 0 WHEN d<>'NOT_CONFIGURED' THEN 1 ELSE (l->'source'->>'tier')::int END,'legacy',l,'sources',coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(rules) x WHERE x->>'permission'=r.key),'[]'::jsonb),'supported',private.base_supported(r.key),'scope',CASE WHEN r.key LIKE 'biz.crm_%' AND d='ALLOW' THEN 'own' ELSE 'native' END,'conflict',EXISTS(SELECT 1 FROM jsonb_array_elements(rules) x WHERE x->>'permission'=r.key AND x->>'effect'='ALLOW') AND EXISTS(SELECT 1 FROM jsonb_array_elements(rules) x WHERE x->>'permission'=r.key AND x->>'effect'='DENY')));END LOOP;RETURN result;END $$;
CREATE OR REPLACE FUNCTION public.base_permissions_effective(_user uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid:=coalesce(_user,auth.uid());BEGIN IF auth.uid() IS NULL OR NOT private.is_active(auth.uid()) OR (u<>auth.uid() AND NOT private.base_org_admin()) THEN RAISE EXCEPTION 'Không có quyền xem phân quyền.';END IF;RETURN jsonb_build_object('user_id',u,'revision',coalesce((SELECT revision FROM base_org_state WHERE id),0),'server_now',now(),'permissions',private.base_effective(u,private.base_config()));END $$;
CREATE OR REPLACE FUNCTION public.base_org_read() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT private.base_org_admin() THEN RAISE EXCEPTION 'Chỉ Super Admin được quản trị phân quyền toàn Base.';END IF;RETURN jsonb_build_object('revision',coalesce((SELECT revision FROM base_org_state WHERE id),0),'config',private.base_config(),'staff',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'name',full_name,'status',status) ORDER BY full_name),'[]') FROM profiles),'catalog',(SELECT coalesce(jsonb_agg(jsonb_build_object('key',key,'label',label,'module',module,'supported',private.base_supported(key)) ORDER BY module,key),'[]') FROM base_permission_catalog),'events',(SELECT coalesce(jsonb_agg(x),'[]') FROM (SELECT id,actor_id,action,before_revision,after_revision,impact,created_at FROM base_permission_events ORDER BY created_at DESC LIMIT 50)x));END $$;
CREATE OR REPLACE FUNCTION public.base_permission_catalog_sync(_catalog jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb;BEGIN IF NOT private.base_org_admin() THEN RAISE EXCEPTION 'Không có quyền quản trị.';END IF;IF jsonb_typeof(_catalog)<>'array' OR jsonb_array_length(_catalog)>1500 THEN RAISE EXCEPTION 'Danh sách quyền không hợp lệ.';END IF;PERFORM pg_advisory_xact_lock(hashtext('base_org'));FOR r IN SELECT value FROM jsonb_array_elements(_catalog) LOOP IF coalesce(r->>'key','')='' OR length(r->>'key')>160 OR coalesce(r->>'label','')='' THEN RAISE EXCEPTION 'Quyền không hợp lệ.';END IF;INSERT INTO base_permission_catalog(key,label,module,dependencies) VALUES(r->>'key',r->>'label',r->>'module',ARRAY(SELECT jsonb_array_elements_text(coalesce(r->'dependencies','[]')))) ON CONFLICT(key) DO UPDATE SET label=excluded.label,module=excluded.module,dependencies=excluded.dependencies;END LOOP;END $$;
DO $$ DECLARE r record;BEGIN FOR r IN SELECT p.oid::regprocedure fn FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE (n.nspname='private' AND p.proname LIKE 'base_%' AND p.proname<>'base_org_admin') OR (n.nspname='public' AND p.proname IN ('base_org_read','base_permission_catalog_sync','base_permissions_effective')) LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon',r.fn);IF r.fn::text LIKE 'private.%' THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM authenticated',r.fn);ELSE EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated,service_role',r.fn);END IF;END LOOP;END $$;